/* Compare source snapshots on reviewed portions or an explicitly supported weight. */
(function(){'use strict';const root=document.querySelector('[data-food-comparison]');if(!root)return;
const F=window.GetMacrosFood,UI=window.GetMacrosFoodUI,C=window.GetMacrosFoodComparison;let items=[];let editing=null;try{items=C.read(localStorage);}catch{}
const basis=root.querySelector('[data-food-compare-basis]'),content=root.querySelector('[data-food-compare-content]'),status=root.querySelector('[data-food-compare-status]');
const labels={cal:'Calories',p:'Protein',c:'Carbs',fat:'Fat',f:'Fiber',na:'Sodium',sugar:'Total sugars'},fmt=v=>F.known(v)?new Intl.NumberFormat('en',{maximumFractionDigits:1}).format(v):'Unknown';
const countryName=code=>(window.GM_MARKETS||{})[code]?.name||({'US-reference':'U.S. food-composition reference','CA-reference':'Canadian food-composition reference'}[code])||code;
function sourceStatus(s){if(s.market==='US-reference')return 'USDA reference serving';if(s.market==='CA-reference')return 'Canadian reference serving';if(s.sourceId?.startsWith('off-'))return 'Imported Open Food Facts record';if(s.status?.includes('calculated'))return 'Calculated from source values';if(s.status?.includes('retailer'))return 'Online retailer label';if(s.status?.includes('official'))return 'Official source record';return 'Source-linked portion';}
function node(tag,text){const n=document.createElement(tag);if(text!==undefined)n.textContent=text;return n;}
const download=node('button','Download comparison card');download.type='button';download.hidden=true;root.querySelector('.food-review-header').append(download);
const share=node('button','Share comparison');share.type='button';share.hidden=true;root.querySelector('.food-review-header').append(share);
share.addEventListener('click',async()=>{try{const url=C.link(items,basis.value,location.origin);await navigator.clipboard.writeText(url);status.textContent='Public food and portion link copied. No diary entries or notes are included.';}catch(e){const input=node('input');input.readOnly=true;input.value=C.link(items,basis.value,location.origin);input.setAttribute('aria-label','Comparison link');status.replaceChildren(node('label','Copy this comparison link'),input);input.focus();input.select();}});
function persist(){try{C.write(localStorage,items);C.writeBasis(localStorage,basis.value);}catch{status.textContent='This browser could not retain the comparison. You can still compare and share it now.';}}
function xml(v){return String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&apos;'}[c]));}
function lines(value,width){const out=[];let line='';for(const word of String(value).split(/\s+/)){if(line.length&&line.length+word.length+1>width){out.push(line);line='';}if(word.length>width){if(line)out.push(line);for(let i=0;i<word.length;i+=width)out.push(word.slice(i,i+width));line='';}else line+=(line?' ':'')+word;}if(line)out.push(line);return out;}
download.addEventListener('click',()=>{if(items.length!==2)return;const numbers=items.map(s=>basis.value==='100g'?F.scale(F.fromSnapshot(s),100,'g'):s.nutrients),rows=[];let y=110;
function text(x,top,value,size=17,color='#244434'){return '<text x="'+x+'" y="'+top+'" font-family="Arial,sans-serif" font-size="'+size+'" fill="'+color+'">'+xml(value)+'</text>';}
rows.push(text(32,45,'GetMacros',24),text(32,77,basis.value==='100g'?'Source nutrition per 100 g':'Reviewed food portions',18));
items.forEach((s,i)=>{const x=i?398:32;const name=lines(s.name,32).slice(0,5);name.forEach((line,j)=>rows.push(text(x,110+j*23,line,18)));rows.push(text(x,240,[s.brand,countryName(s.market)].filter(Boolean).join(' · '),14),text(x,267,basis.value==='100g'?'100 g':F.formatPortion(s),14));});
y=315;for(const k of Object.keys(labels)){rows.push(text(32,y,labels[k]+' ('+F.units[k]+')',15));rows.push(text(290,y,fmt(numbers[0][k]),18),text(650,y,fmt(numbers[1][k]),18));y+=37;}
const attribution=items.some(s=>s.sourceId==='health-canada-cnf-2026')?'Canadian reference data: Health Canada, CNF 2026. Contains information licensed under the Open Government Licence—Canada.':'Values retain their source editions. Unknown values are not zero.';
const extra=items.some(function usesOff(s){return s.sourceId?.startsWith('off-')||s.recipeParts?.some(usesOff)})?' Contains information from Open Food Facts — ODbL 1.0. https://openfoodfacts.org/ · https://opendatacommons.org/licenses/odbl/1-0/':'';
for(const line of lines(attribution+extra,91)){rows.push(text(32,y+10,line,13));y+=19;}y+=25;
items.forEach((s,i)=>{rows.push(text(32,y,'Food '+(i+1)+' · '+(s.sourcePublished||'Source edition unavailable'),14));y+=22;for(const line of lines(s.sourceUrl||'Saved source',95)){rows.push(text(32,y,line,12));y+=17;}y+=16;});
rows.push(text(32,y+10,'Different recipes or portions are not a health ranking. getmacros.net/food-library.html',13));y+=45;
const svg='<svg xmlns="http://www.w3.org/2000/svg" width="764" height="'+y+'" viewBox="0 0 764 '+y+'"><title>GetMacros source food comparison</title><rect width="764" height="'+y+'" rx="16" fill="#fffdf8"/><path d="M0 0H764V8H0Z" fill="#2c6443"/>'+rows.join('')+'</svg>',url=URL.createObjectURL(new Blob([svg],{type:'image/svg+xml'})),a=node('a');a.href=url;a.download='getmacros-food-comparison.svg';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);status.textContent='Comparison card downloaded with portions, markets and source links.';
});
function render(){root.hidden=!items.length&&!root.hasAttribute('data-comparison-workspace');content.replaceChildren();share.hidden=items.length!==2;download.hidden=items.length!==2;basis.disabled=items.length<2;if(!items.length){status.textContent='Choose your first food below, review its portion, then choose Compare this portion.';return;}const weight=items.every(s=>{try{F.scale(F.fromSnapshot(s),100,'g');return true}catch{return false}});basis.querySelector('[value="100g"]').disabled=!weight;if(!weight)basis.value='portions';
 download.hidden=items.length!==2;
 const grid=node('div');grid.className='food-comparison-identities';items.forEach((s,i)=>{const article=node('article'),h=node('h3',s.name),p=node('p',[s.brand,countryName(s.market),basis.value==='100g'?'100 g':F.formatPortion(s)].filter(Boolean).join(' · '));article.append(node('span','Food '+(i+1)),h,p,node('p',sourceStatus(s)));if(s.sourceUrl?.startsWith('https://')){const a=node('a','Source · '+(s.sourcePublished||'edition unavailable'));a.href=s.sourceUrl;article.append(a);}const notes=node('details');notes.append(node('summary','Source notes & attribution'),node('p','Source record: '+s.recordId+' · '+s.sourceId));for(const value of [s.attribution,...(s.flags||[])].filter(Boolean))notes.append(node('p',value));notes.append(node('p','Source status: '+s.status+' · '+(s.sourceChecked?'Checked '+s.sourceChecked:'Check date unavailable')+(s.retrievedAt?' · Retrieved '+s.retrievedAt:'')));if(s.licenseUrl){const license=node('a',s.license||'Source license');license.href=s.licenseUrl;notes.append(license);}article.append(notes);const actions=node('div');actions.className='comparison-food-actions';const log=node('a','Log this portion');log.href='/food-diary.html?food='+encodeURIComponent(s.recordId)+'&quantity='+(basis.value==='100g'?100:s.quantity)+'&measure='+encodeURIComponent(basis.value==='100g'?'g':s.measure)+(window.GM_MARKETS?.[s.market]?'&market='+s.market:'');actions.append(log);const edit=node('button','Edit portion');edit.type='button';edit.addEventListener('click',()=>{editing={index:i,recordId:s.recordId,identity:JSON.stringify([s.recordId,s.version,s.name,s.quantity,s.measure])};UI.review(F.fromSnapshot(s),{quantity:s.quantity,measure:s.measure});});actions.append(edit);const remove=node('button','Remove');remove.type='button';remove.addEventListener('click',()=>{items.splice(i,1);persist();render();root.querySelector('[data-food-compare-clear]').focus({preventScroll:true});});actions.append(remove);article.append(actions);grid.append(article);});if(items.length===2){const versus=node('span','vs');versus.className='food-comparison-versus';versus.setAttribute('aria-hidden','true');grid.insertBefore(versus,grid.children[1]);}content.append(grid);
 if(items.length<2){status.textContent='Add one more reviewed food to compare.';basis.disabled=true;return;}basis.disabled=false;status.textContent=basis.value==='100g'?'Equal source-supported weights. Preparation and country can still differ.':weight?'Portions can differ. Choose 100 g for an equal-weight view.':'A gram weight is unavailable for at least one food. Compare the named portions; these are not equal weights.';
 const table=node('table'),caption=node('caption',basis.value==='100g'?'Nutrition per 100 g of each source food':'Nutrition in the two reviewed portions');table.append(caption);const thead=node('thead'),head=node('tr');head.append(node('th','Nutrient'));items.forEach((_,i)=>head.append(node('th','Food '+(i+1))));[...head.children].forEach(n=>n.scope='col');thead.append(head);table.append(thead);const tbody=node('tbody'),numbers=items.map(s=>basis.value==='100g'?F.scale(F.fromSnapshot(s),100,'g'):s.nutrients);
 for(const k of Object.keys(labels)){const row=node('tr'),title=node('th',labels[k]+' ('+F.units[k]+')');title.scope='row';row.append(title);numbers.forEach(n=>row.append(node('td',fmt(n[k]))));tbody.append(row);}table.append(tbody);const wrap=node('div');wrap.className='table-wrap';wrap.tabIndex=0;wrap.setAttribute('role','region');wrap.setAttribute('aria-label','Reviewed food nutrition comparison');wrap.append(table);content.append(wrap);
 const notice=node('p','Unknown values stay unknown. This comparison does not assign a health score or assume that products with the same name have the same recipe.');notice.className='food-search-hint';content.append(notice);
}
document.querySelector('[data-review-compare]').addEventListener('click',()=>{try{if(root.getAttribute('aria-busy')==='true')throw Error('The shared comparison is still loading. Add this food when it is ready.');const snapshot=UI.snapshot();if(editing&&editing.recordId===snapshot.recordId){const current=items[editing.index];if(!current||JSON.stringify([current.recordId,current.version,current.name,current.quantity,current.measure])!==editing.identity)throw Error('The comparison changed while you were reviewing. Close this review and choose the current food.');const next=[...items];next[editing.index]=snapshot;items=C.validate(next);}else items=C.add(items,snapshot);editing=null;document.querySelector('#food-review').close();render();persist();root.querySelector('[data-food-compare-clear]').focus();}catch(e){status.textContent=e.message;document.querySelector('[data-review-error]').textContent=e.message;}});
basis.addEventListener('change',()=>{render();persist();});root.querySelector('[data-food-compare-clear]').addEventListener('click',()=>{items=[];render();persist();document.querySelector('[data-food-query]').focus({preventScroll:true});});
document.querySelector('#food-review').addEventListener('close',()=>{editing=null;});basis.value=C.readBasis(localStorage);render();
const params=new URLSearchParams(location.search),ids=params.getAll('item').slice(0,2);
if(ids.length){content.hidden=true;basis.disabled=true;share.disabled=true;download.disabled=true;root.querySelector('[data-food-compare-clear]').disabled=true;status.textContent='Loading source portions…';root.setAttribute('aria-busy','true');(async()=>{const versions=params.getAll('version'),quantities=params.getAll('quantity'),measures=params.getAll('measure'),loaded=await Promise.all(ids.map(async(id,i)=>{if(id.length>300||!/^(order:|fdc:\d+$|cnf:\d+$|branded:)/.test(id))throw Error('A linked food is unavailable. Choose another food below.');const record=await window.GetMacrosLibrary.get(id),measure=measures[i]||(record.basis.unit==='g'?'g':'serving'),quantity=quantities[i]===undefined?(measure==='g'?100:1):Number(quantities[i]);return F.snapshot(record,quantity,measure);}));items=params.get('append')==='1'?items:[];loaded.forEach(s=>items=C.add(items,s));basis.value=params.has('basis')?(params.get('basis')==='100g'?'100g':'portions'):C.readBasis(localStorage);render();persist();if(loaded.some((s,i)=>versions[i]&&String(s.version)!==versions[i]))status.textContent+=' A linked source edition has changed; the current record is shown. Check its source before using it.';})().catch(e=>{render();status.textContent=e.message;}).finally(()=>{root.removeAttribute('aria-busy');content.hidden=false;share.disabled=false;download.disabled=false;root.querySelector('[data-food-compare-clear]').disabled=false;document.dispatchEvent(new CustomEvent('food-comparison-ready'));});}
})();
